/// `root_as_rsd_unchecked`.
pub fn root_as_rsd_with_opts<'b, 'o>(
  opts: &'o ::flatbuffers::VerifierOptions,
  buf: &'b [u8],
) -> Result<RSD<'b>, ::flatbuffers::InvalidFlatbuffer> {
  ::flatbuffers::root_with_opts::<RSD<'b>>(opts, buf)
}
#[inline]
/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `RSD` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_rsd_unchecked`.
pub fn size_prefixed_root_as_rsd_with_opts<'b, 'o>(
  opts: &'o ::flatbuffers::VerifierOptions,
  buf: &'b [u8],
) -> Result<RSD<'b>, ::flatbuffers::InvalidFlatbuffer> {
  ::flatbuffers::size_prefixed_root_with_opts::<RSD<'b>>(opts, buf)
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a RSD and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `RSD`.
pub unsafe fn root_as_rsd_unchecked(buf: &[u8]) -> RSD<'_> {
  unsafe { ::flatbuffers::root_unchecked::<RSD>(buf) }
}
#[inline]
/// Assumes, without verification, that a buffer of bytes contains a size prefixed RSD and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `RSD`.
pub unsafe fn size_prefixed_root_as_rsd_unchecked(buf: &[u8]) -> RSD<'_> {
  unsafe { ::flatbuffers::size_prefixed_root_unchecked::<RSD>(buf) }
}
pub const RSD_IDENTIFIER: &str = "$RSD";

#[inline]
pub fn rsd_buffer_has_identifier(buf: &[u8]) -> bool {
  ::flatbuffers::buffer_has_identifier(buf, RSD_IDENTIFIER, false)
}

#[inline]
pub fn rsd_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
  ::flatbuffers::buffer_has_identifier(buf, RSD_IDENTIFIER, true)
}

#[inline]
pub fn finish_rsd_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<RSD<'a>>) {
  fbb.finish(root, Some(RSD_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_rsd_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>, root: ::flatbuffers::WIPOffset<RSD<'a>>) {
  fbb.finish_size_prefixed(root, Some(RSD_IDENTIFIER));
}
